#include <iostream>
#include <iomanip>

int main() {
    int a = 0;
    int b = 10;

    // Short-circuit demonstration: (a != 0) is false, so (b / a > 1) is never evaluated
    bool safeDivide = (a != 0) && ((b / a) > 1);

    std::cout << std::boolalpha;
    std::cout << "Safe divide evaluation: " << safeDivide << "\n";

    // Equality vs Assignment demonstration
    int status = 0;
    if (status == 0) {
        std::cout << "Equality check succeeded: status is zero\n";
    }

    // Safe floating-point loop using integer scaling (Self-Review 5.3b fix)
    std::cout << "Scaled loop fractions:";
    for (unsigned int count = 1; count <= 5; ++count) {
        std::cout << ' ' << (static_cast<double>(count) / 10.0);
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    // Print a 4x5 grid of asterisks side-by-side using nested loops
    const unsigned int rows = 4;
    const unsigned int cols = 5;
    for (unsigned int i = 1; i <= rows; ++i) {
        for (unsigned int j = 1; j <= cols; ++j) {
            std::cout << '*';
        }
        std::cout << '\n';
    }

    // Exercise 5.2b formatting demonstration
    double val = 333.546372;
    std::cout << std::fixed << std::left
              << std::setprecision(1) << std::setw(10) << val
              << std::setprecision(2) << std::setw(10) << val
              << std::setprecision(3) << std::setw(10) << val
              << '\n';

    return 0;
}
